import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html'
})
export class LoginComponent {
  form: FormGroup;
  loading = false;
  error = '';

  constructor(
    private fb: FormBuilder,
    private auth: AuthService,
    private router: Router
  ) {
    this.form = this.fb.group({
      login: ['', [Validators.required, Validators.email]],
      password: ['', Validators.required]
    });
  }

  onSubmit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    this.auth.login(this.form.value).subscribe({
      next: () => {
        this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        this.loading = false;
        this.error = err.error?.message || 'Identifiants incorrects';
      }
    });
  }
}
<div class="auth-wrapper">
  <div class="auth-card">
    <div class="logo">
      <i class="bi bi-heart-pulse"></i>
    </div>
    <h2>Connexion</h2>
    <p class="subtitle">VetCare Manager – PetHealth Solutions</p>

    <div *ngIf="error" class="alert alert-danger py-2">{{ error }}</div>

    <form [formGroup]="form" (ngSubmit)="onSubmit()">
      <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" formControlName="login" placeholder="adminpethealth@gmail.com">
        <div *ngIf="form.get('login')?.touched && form.get('login')?.invalid" class="text-danger small mt-1">
          Email valide requis
        </div>
      </div>
      <div class="mb-3">
        <label class="form-label">Mot de passe</label>
        <input type="password" class="form-control" formControlName="password" placeholder="••••••••">
        <div *ngIf="form.get('password')?.touched && form.get('password')?.invalid" class="text-danger small mt-1">
          Mot de passe requis
        </div>
      </div>
      <button type="submit" class="btn btn-primary w-100 py-2" [disabled]="loading || form.invalid">
        <span *ngIf="loading" class="spinner-border spinner-border-sm me-2"></span>
        Se connecter
      </button>
    </form>

    <p class="text-center mt-3 mb-0 text-muted" style="font-size:0.9rem;">
      Pas encore de compte ?
      <a routerLink="/register" class="fw-semibold">S'inscrire</a>
    </p>
  </div>
</div>
